<?php
try{$period=budget_month($_GET['month']??date('Y-m'));}catch(InvalidArgumentException $e){$period=date('Y-m');}
$start=$period.'-01';$end=date('Y-m-d',strtotime($start.' +1 month'));
$plans=budget_rows('SELECT * FROM budget_plans WHERE period=? ORDER BY category','s',[$start]);
$actuals=budget_rows('SELECT category,SUM(amount) actual FROM expenses WHERE expense_date>=? AND expense_date<? GROUP BY category','ss',[$start,$end]);
$comparison=[];foreach($plans as $p)$comparison[$p['category']]=['planned'=>(float)$p['amount'],'actual'=>0];
foreach($actuals as $a){$comparison[$a['category']]??=['planned'=>0,'actual'=>0];$comparison[$a['category']]['actual']=(float)$a['actual'];}
$plannedTotal=array_sum(array_column($comparison,'planned'));$actualTotal=array_sum(array_column($comparison,'actual'));
$edit=[];foreach($plans as $p)if((int)$p['id']===(int)($_GET['edit']??0))$edit=$p;
?>
<form method="get" class="erp-period-filter"><input type="hidden" name="page" value="admin"><input type="hidden" name="tab" value="<?= e($tab) ?>"><label>Periode anggaran <input type="month" name="month" value="<?= e($period) ?>" min="2000-01" max="2100-12" required></label><button class="erp-btn">Tampilkan</button></form>
<div class="erp-kpis erp-budget-kpis"><article><span>Rencana anggaran</span><strong><?= rupiah($plannedTotal) ?></strong><small><?= e($period) ?></small></article><article><span>Pengeluaran tercatat</span><strong><?= rupiah($actualTotal) ?></strong><small>Sumber: menu Pengeluaran</small></article><article><span><?= $actualTotal>$plannedTotal?'Melebihi anggaran':'Sisa anggaran' ?></span><strong><?= rupiah(abs($plannedTotal-$actualTotal)) ?></strong><small>Selisih rencana dan realisasi</small></article></div>
<?php if($tab==='budget'):?>
<div class="erp-grid"><section class="erp-card"><div class="erp-card-head"><div><h2><?= $edit?'Edit anggaran':'Rencana biaya baru' ?></h2><p>Satu anggaran per kategori per bulan.</p></div></div><form method="post" class="erp-form"><input type="hidden" name="action" value="erp_budget_save"><input type="hidden" name="budget_csrf" value="<?= e(budget_csrf()) ?>"><input type="hidden" name="budget_id" value="<?= (int)($edit['id']??0) ?>"><label>Bulan<input type="month" name="period" value="<?= e($period) ?>" min="2000-01" max="2100-12" required></label><label>Kategori<select name="category" required><?php foreach(budget_categories() as $category):?><option <?= ($edit['category']??'')===$category?'selected':'' ?>><?= e($category) ?></option><?php endforeach;?></select></label><label>Nominal rencana (Rp)<input type="number" name="amount" step="0.01" min="0.01" max="999999999.99" value="<?= e($edit['amount']??'') ?>" required></label><label>Catatan<input name="notes" maxlength="255" value="<?= e($edit['notes']??'') ?>" placeholder="Contoh: promosi koleksi baru"></label><button class="erp-btn">Simpan anggaran</button><?php if($edit):?><a href="?page=admin&tab=budget&month=<?= e($period) ?>">Batal edit</a><?php endif;?></form></section>
<section class="erp-card"><div class="erp-card-head"><div><h2>Rencana anggaran biaya</h2><p><?= count($plans) ?> kategori pada periode ini.</p></div><a href="?page=admin&tab=budget_report&month=<?= e($period) ?>">Lihat realisasi</a></div><div class="erp-table-wrap"><table><thead><tr><th>Kategori</th><th>Anggaran</th><th>Catatan</th><th>Aksi</th></tr></thead><tbody><?php foreach($plans as $p):?><tr><td><?= e($p['category']) ?></td><td><?= rupiah($p['amount']) ?></td><td><?= e($p['notes']) ?></td><td><a href="?page=admin&tab=budget&month=<?= e($period) ?>&edit=<?= (int)$p['id'] ?>">Edit</a><form method="post" onsubmit="return confirm('Hapus rencana anggaran ini? Pengeluaran tidak akan dihapus.')"><input type="hidden" name="action" value="erp_budget_delete"><input type="hidden" name="budget_csrf" value="<?= e(budget_csrf()) ?>"><input type="hidden" name="budget_id" value="<?= (int)$p['id'] ?>"><input type="hidden" name="period" value="<?= e($period) ?>"><button class="erp-budget-delete">Hapus</button></form></td></tr><?php endforeach;?><?php if(!$plans):?><tr><td colspan="4">Belum ada anggaran. Tambahkan rencana biaya melalui formulir.</td></tr><?php endif;?></tbody></table></div></section></div>
<?php else:?>
<section class="erp-card"><div class="erp-card-head"><div><h2>Anggaran vs realisasi</h2><p>Pengeluaran dicocokkan berdasarkan kategori dan bulan transaksi.</p></div><a href="?page=admin&tab=finance">Catat pengeluaran</a></div><div class="erp-table-wrap"><table><thead><tr><th>Kategori</th><th>Rencana</th><th>Realisasi</th><th>Sisa / (lebih)</th><th>Status</th></tr></thead><tbody><?php foreach($comparison as $category=>$v):?><tr><td><?= e($category) ?></td><td><?= rupiah($v['planned']) ?></td><td><?= rupiah($v['actual']) ?></td><td><?= rupiah($v['planned']-$v['actual']) ?></td><td><span class="erp-pill <?= $v['actual']>$v['planned']?'erp-over-budget':'' ?>"><?= !$v['planned']?'Belum dianggarkan':($v['actual']>$v['planned']?'Melebihi anggaran':'Dalam anggaran') ?></span></td></tr><?php endforeach;?><?php if(!$comparison):?><tr><td colspan="5">Belum ada anggaran atau pengeluaran pada bulan ini.</td></tr><?php endif;?></tbody></table></div></section>
<p class="erp-budget-note">Realisasi hanya menghitung biaya yang tercatat di menu Pengeluaran. Purchase order tidak otomatis dianggap sebagai pengeluaran. Modul ini belum mencakup persetujuan anggaran atau akuntansi penuh.</p>
<?php endif;?>
